    "intro": "拍片的时候，我是编导；看后台的时候，我做运营；站上讲台，又成了教书匠。\n这些身份在我这儿不打架。拍片练出来的叙事，用来讲课；运营里试过的办法，带回课堂。不同的经历，常常能互相递个好点子。\n书架上住着心理学、法律和小说，屏幕里有电影和番剧。想认真把事情做好，也想给生活留点“不务正业”的快乐。\n可以聊项目，也可以聊最近看过的故事。工作有分工，好奇心没有。",
