                "沈春禾与陆青山",
                "两人从一次码头帮助认识。春禾先记住他的礼貌和破袖，青山在书局进一步认识她教工友识字的想法。第三次相遇后，他进入她的家庭与夜课，双方在数月合作中产生爱意。离别、书信和药铺重逢，使关心从日常照顾变成对彼此安危的牵挂。双方没有正式确立婚恋身份，却知道自己在对方心里的分量。",
