                "裂口与缝补",
                "1926年码头拾纸时，青山右袖口外缘被铁钩划开约两三厘米。母女在沈家二楼把袖口里层翻出，垫一小片深色棉布，用细黑线合拢裂边。春禾用几针蓝线固定里侧衬布末角。袖口翻回后外侧平顺，只有拿在手里翻看才看得清里侧蓝针脚，穿着不会硌手。"
