      "title": "珠江桥牌春节情景稿（品牌部版本）",
      "sections": [
        {
          "title": "原稿正文",
          "paragraphs": [
            "视频一：单身篇",
            "场景：单身青年（小张）回家过年，一进门就被亲戚围住，七嘴八舌地询问个人问题。",
            "剧情：",
            "小张尴尬地笑着，亲戚们你一言我一语，气氛紧张。",
            "小张突然灵机一动，拿出一酱成菜产品，说：“虽然我没带对象回来，但我带了这个，今年我给大家露一手，做个经典粤味大餐！”",
            "亲戚们半信半疑，但小张自信满满地走进厨房。",
            "快速剪辑展示小张使用酱包烹饪的过程，轻松快捷。",
            "菜肴上桌，色香味俱全，亲戚们惊艳，纷纷称赞。",
            "小张得意地说：“单身怎么了？我的生活照样可以很精彩！”",
            "结尾：屏幕上出现“一酱成菜，美味不翻车，过年回家露一手”。",
            "视频二：家庭篇",
            "场景：一家三口，忙碌准备年夜饭。",
            "剧情：",
            "刚参加工作回不去过年，自己不会做饭，然后这时候门铃响了，是父母跑过来陪她过年，给送吃的",
            "第二年回家了，想要好好孝敬父母，给父母露一手",
            "小李去做饭，发现比想象的更难，搞半天，手忙脚乱。",
            "小李突然想到经常看到的珠江桥牌一酱成菜，用它来帮忙。",
            "快速剪辑小李用酱包做出一道道美味的菜肴，父母惊讶。",
            "年夜饭上，家人围坐，品尝小李的手艺，赞不绝口。",
            "小李骄傲地说：“家庭温暖，美食相伴，这就是年的味道！”",
            "结尾：屏幕上出现“一酱成菜，美味不翻车，过年回家露一手”。",
            "视频三：情侣篇",
            "场景：一对情侣（小王和小丽）去小丽家过年，小王紧张不安，担心表现不佳。",
            "剧情：",
            "小丽的父母严肃，小王更加紧张。",
            "午饭时间，小王决定表现一下，来到厨房帮忙，瞬间傻了眼，不知道从何下手",
            "小王突然想起珠江桥牌的一酱成菜，决定用它来帮忙赢得好感。",
            "小王在厨房忙碌，小丽好奇地跟进来。",
            "快速剪辑小王用酱包烹饪，小丽帮忙，两人合作无间。",
            "菜肴完成，小丽的父母品尝后，露出满意的笑容。",
            "小王松了一口气，小丽的父母点头称赞：“这小伙子，手艺不错！”",
            "结尾：屏幕上出现“一酱成菜，美味不翻车，过年回家露一手”。"
          ]
        }
      ],
      "summary": "客户项目原稿 · 脚本文案",
