            "1",
            "在繁忙的三家半，一道美味即将诞生。",
            "看，这就是我们的主角——烤乳猪。",
            "金黄酥脆的外皮，散发出令人垂涎的香气。",
            "一刀下去，露出鲜嫩多汁的肉质。",
