                "",
                "",
                "您想啊，肠瘘一出现，肠子里那些东西，像腐蚀性超强的消化液，还有没彻底消化的食物，就会顺着瘘口流到腹腔或者体表别的地方。这时候，消化液就像一把把尖锐的小刀，在肚子里划来划去，刺激着周围组织，能不疼吗？\n不光如此，腹腔进了这些 “外来户”，免疫系统立马警觉，炎症反应紧接而来，一个劲儿地刺激神经末梢，疼痛起来更是变本加厉。\n除此之外，肠瘘还可能导致肠道抽筋，像痉挛一样收缩，这也是腹痛的一大 “祸根”。\n\n【添加案例】\n\n所以说呀，肠瘘引发的腹痛，不要觉得不是小打小闹的毛病，它意味着你的身体内部正遭受重创，千万别硬撑，一定要及时跟医生说，好让医生调整治疗方案。\n患者自己呢，可以把腹痛啥时候发作、疼到啥程度、有没有别的伴随症状，都详细记下来，这能帮医生更精准判断病情。\n家属也别干着急，在旁边多安抚患者情绪，可以轻柔地给患者腹部按摩按摩，但要注意避开瘘口部位，可以稍微减轻点儿患者的难受劲儿。"
