      "id": "education-02",
      "category": "家庭教育",
      "title": "6.讲一万遍道理，不如做好一件事，和孩子关系搞好其实就这么简单",
      "sections": [
        {
          "title": "原稿正文",
          "paragraphs": [
            "讲一万遍道理，不如做好一件事，和孩子关系搞好其实就这么简单",
            "沟通大于内容（语言的力量。）你跟孩子聊天不要去奔着内容去，你聊什么都能聊，你不要有目的。你们有没有听过龟兔赛跑的故事？请问一下是兔子赢了还是龟赢了？龟赢了，那请问兔子服吗？我肯定不服，我那么厉害，你怎么能让乌龟赢呢？我不服啊。 100 年后，兔子又去找到了乌龟，我还要和你再比一次，我不服气。乌龟说来就来，谁怕谁。兔子说，这次我要重新制定规则，我们去山上比从山上到山下看谁的速度更快，然后找了个发令员，一枪，啪，两个人一跃而下，兔子一路狂奔，然后在路上摔了个人仰马翻，然后乌龟把四个手跟一个脑袋一缩，从头到尾的滚下去，请问谁赢了？又是乌龟赢了。\n\n兔子走到终点站，伤痕累累的说，凭什么我四条腿都跑不过你这个慢慢爬的，气死我了， 100 年过去了，兔子还是不服，兔子说，我还要和你再比一次，我要跟你比平路，找一个 400 米的一个操场，我要跟你保 400 米。发令员一声响，啪的一声，两个人嗖的一下子又冲了出去，临近终点的时候，兔子说，这次肯定是我赢了，然后兔子一回头，发现乌龟还没到，兔子很开心，我肯定赢了，转身正准备越过终点线的时候，发现乌龟已经在那等他了。兔子说，你又是怎么做到的呀？乌龟说，我咬着你的尾巴过来的，你一回头一甩就把我甩过终点站了。\n\n请问 100 年后兔子服不服？兔子又不服了，兔子说我还要和你再比一次，这次不跟你比 400 米了，我们就比 100 米，然后两个人找了个发令员，发令员一声枪响，啪的一声，两个人歘的一下子又冲了出去，临近终点的时候，兔子又自信回头了，他说，这次你肯定赢不了我了，谁知道一回头发现乌龟又到终点站了。\n\n兔子说，你这次又是怎么做到的呢？我把尾巴都藏起来了，我夹着尾巴跑的。乌龟说这都什么时代了？ 21 世纪了。我打了个滴滴来的，请问一百年后兔子服不服？各位听到了这你还想不想往下继续听？你想不想了解下一个故事？人是记不住道理的，只能记住故事。所以你跟孩子之间的关系变得好，就是你要去学会主动创造，和他发生一些故事，你讲一万个道理，都不如你跟他有一段共同的故事，他能记得更久，这就是核心观念。"
          ]
        }
      ],
