            "有人说娃哈哈是没有营养的糖水，可能跟现在比，娃哈哈的营养确实比不上那些新兴的饮料，但是它诞生的背景是 1996 年的，你们知道在 1996 年的时候，我们大部分人，全部都营养不良，那个时候谁能够吃得起很贵的营养呀？如果没有宗老做这个娃哈哈，我们这一代的人大部分人都营养不良，而且这么多年了没涨价，有人说今年春晚娃哈哈上了春晚，有人可能说，这么垃圾的，能上春晚这个档次舞台，为什么？因为娃哈哈不涨价，觉得不适合那个春晚，那个档次，那人家钟老就是想为了我们的那些当时那些年轻人能够有一个好的产品。",
            "我想请问，如果当时没有这样的企业家，我们当时那群 80 后、 90 后吃什么？我小时候我记得我最好的就是想喝个娃哈哈，我现在都喝娃哈哈，我不跟你开玩笑呀，好多年前我们家的纯净水我都是喝娃哈哈的。我也不知道为什么当时选择娃哈哈，现在就知道了，娃哈哈的纯净水是可以给我们国家实验室去做实验的干净程度，所以大家以后多支持娃哈哈。",
