            "到底什么样的激励，能让员工抢着干活？【字幕逐字弹出】",
            "【敲桌音效】",
            "记住三个'看得见'！",
            "第一，目标看得见",
            "【素材：赛车冲刺动画】。",
            "就像我上周给销售团队定的：当天签单前三名，下班前直接发现金红包！【钞票音效】",
            "进度看得见。【字幕滚动】",
            "用实时排行榜，每个人都能看到自己离奖励差多少。【素材：销售数据大屏】",
            "记住：人只会为自己能赢的比赛拼命！",
            "回报看得见。【敲黑板音效】",
            "别搞什么年终兑现，员工要的是即时反馈！",
            "就像我们技术部，攻克一个BUG当场发200，比月底多发2000都管用！",
            "员工不是不听话，是你不懂人性。【字幕放大】",
            "版本二：",
            "你知道为什么员工在你这就躺平，换个公司就拼命？",
            "根本不是你给的钱少！",
            "我们调研了500家企业发现：【素材：数据图表】",
            "75%的员工离职，是因为感受不到即时激励。",
            "真正的激励要满足两个点：【音效：叮】",
            "一是短周期，二是高感知。",
            "就像打游戏，为什么上瘾？",
            "因为每杀个怪都有金币！",
            "具体方法我教你三招。",
            "第一招：设置每日冠军榜。",
            "我们公司前台都放个电子屏，实时显示销售Top3的照片和奖金数。",
            "激励额度有讲究。",
            "建议把大目标拆成小目标：比如10万业绩奖1万，不如每完成2万奖2000。",
            "最关键的是时机！",
            "早上布置任务时就要说清奖励，下班前必须兑现。",
            "拖延一天，效果减半！",
            "记住：员工要的不是承诺，而是立刻能装进口袋的胜利。",
